 const rows = admitPluginCatalogV1(synthetic(), authority()), catalog = pluginCatalogV1(rows);
 expect(catalog.plugins[0].capabilities).toEqual(["media.render"]);
 expect(catalog.extensions[0].extends).toBe("custom.host");
});


